steps.analogousExample:
// Example of a base interface
interface Product {
  id: number;
  title: string;
  price: number;
  inStock: boolean;
}

// Example: Applying Partial to an interface
interface Product {
  id: number;
  name: string;
}

type PartialProduct = Partial<Product>; // All properties become optional

// Example: Using Required with an interface
interface Product {
  id?: number;
  name?: string;
}

type RequiredProduct = Required<Product>; // All properties now required

